	var carg1 *C.gchar               // in, none, string, nullable
	var carg2 **C.gchar              // in, transfer: none, scope: call, implicit: false, skip: false, optional: false, nullable: true, caller-allocates: false, has closure: false, has destroy: false, nullable
	var carg3 C.guint64              // in, casted
	var carg4 C.GTestSubprocessFlags // in, casted

	if testPath != "" {
		carg1 = (*C.gchar)(unsafe.Pointer(C.CString(testPath)))
		defer C.free(unsafe.Pointer(carg1))
	}
	if envp != nil {
		panic("unimplemented conversion of *typesystem.Array (gchar**)")
	}
	carg3 = C.guint64(usecTimeout)
	carg4 = C.GTestSubprocessFlags(testFlags)

	C.g_test_trap_subprocess_with_envp(carg1, carg2, carg3, carg4)
	runtime.KeepAlive(testPath)
	runtime.KeepAlive(envp)
	runtime.KeepAlive(usecTimeout)
	runtime.KeepAlive(testFlags)
